HELP_TOPICS = {'mode_border_plate': {'title': 'Forma base: Cornice (Border) vs. Piastra / Inlay (Plate)', 'short': 'Alterna tra una cornice aperta (Border) e una piastra continua in metallo o vetro (Plate).', 'detail': '• CORNICE (Border): il centro resta aperto (trasparente) per incorniciare la tua foto o grafica.\n• PIASTRA / INLAY (Plate): il centro viene riempito come piastra piena, spazzolata, in vetro semitrasparente o letto inlay colorato (ideale per loghi, badge e targhette).'}, 'grow_direction': {'title': 'Direzione di crescita (Esterno, Interno, Centrato)', 'short': 'Controlla se la cornice cresce verso l’esterno, l’interno o centrata sul bordo della selezione.', 'detail': '• Verso l’esterno (Espandi immagine): la cornice cresce fuori dalla selezione. Se manca margine, Borderlay espande automaticamente la tela in GIMP.\n• Verso l’interno: la cornice cresce dal bordo verso il centro.\n• Entrambi (Centrato): la cornice sta a cavallo del bordo (50 % esterno, 50 % interno).'}, 'corner_radii': {'title': 'Angoli e raggi (Raggio esterno e interno)', 'short': 'Regola l’arrotondamento degli angoli esterni e interni (0 px = giunto a 45° netto).', 'detail': '• Morbido / Medio / Leggero (Raggio > 0 px): crea angoli concentrici arrotondati come una piastra stampata.\n• Taglio 45° (0 / 0 px): crea una cornice classica a 90° con veri giunti diagonali a 45°.\n• Nella scheda «2. Geometria, raggi e 3D» i due raggi si regolano separatamente in pixel.'}, 'shape_toolbox': {'title': 'Forme di selezione e allineamento', 'short': 'Imposta una forma come selezione e la allinea. Non renderizza alcuna cornice.', 'detail': '• Tocca una categoria in alto. Ogni forma è una tessera con il suo ID sotto (es. leaf.heart), selezionabile anche sotto l’anteprima grande.\n• Dimensione, angolo e parametri disegnano subito la forma colorata sull’immagine.\n• Applica rimuove il colore e imposta la selezione. Chiudi senza applicare rimuove il colore e ripristina la selezione precedente.\n• Look include forme base, un’onda e un sorriso.\n• Atelier e Team aggiungono fiamme, ingranaggi, foglie, ornamenti, motivi festivi, archi, parametri onda, occhiolino e angolo.\n• Una selezione rettangolare fa da cornice: la forma parte centrata con le proprie proporzioni. Senza selezione parte al centro al 60 % del lato corto.\n• Allinea aggancia la forma a quella cornice; le frecce spostano a passi in pixel anche oltre. Si sposta la forma, non un livello.'}, 'shape_rotation': {'title': 'Ruota forma di selezione (Angolo e perno a 9 punti)', 'short': 'Ruota solo la geometria della cornice attorno al perno scelto — l’immagine resta invariata!', 'detail': '• Angolo (-180° a +180°): ruota la geometria della cornice o della piastra.\n• Foglia: punta in alto, gambo in basso. Il perno «bordo inferiore centro» porta il gambo al centro della rosetta.\n• Perno: imposta il punto di ancoraggio (Centro, Angolo alto-sinistra, ecc.).\n• Importante: la foto NON viene ruotata e l’illuminazione resta coerente.'}, 'repeat_rotation': {'title': 'Rotazione ripetuta (Angolo 1 -> Angolo 2, passo e dissolvenza)', 'short': 'Genera automaticamente una serie ruotata (ventaglio / caleidoscopio) con dissolvenza progressiva.', 'detail': '• Angolo iniziale 1 e finale 2 (°): definisce l’intervallo angolare della ripetizione.\n• Passo (°): incremento tra le copie.\n• Cicli: ripete il ciclo spostando leggermente ogni passaggio con dissolvenza continua.\n• o fino all’angolo: 0 usa solo i cicli; un valore maggiore continua il passo con cicli a 1.\n• Passi dissolvenza (%): sfuma gradualmente l’opacità dalla prima copia (100 %) all’ultima.'}, 'inlay_color': {'title': 'Colore vetro e inlay (incl. contagocce e campioni)', 'short': 'Imposta il colore per «Vetro cristallo colorato» e per le gole e piastre inlay.', 'detail': 'Dove agisce questo colore?\n1. Con «Vetro cristallo colorato», colora l’intero corpo in vetro e la rifrazione.\n2. Con «Sede inlay colorata» in modalità Piastra, colora lo specchio interno.\n3. Nell’editor multizona, colora le zone con materiale «Colore Inlay (inlay)».\n\nConsiglio: clicca sulla barra colore per ruota e contagocce oppure scegli una delle 8 gemme.'}, 'metal_gradient': {'title': 'Sfumatura metallo e ampiezza di transizione', 'short': 'Sceglie tra la curva fisica a 7 punti della lega e i gradienti nativi di GIMP.', 'detail': '• Curva interna a 7 punti (Consigliato): calcola la riflessione fisica luce/ombra per ogni metallo.\n• Gradiente GIMP: sostituisce la curva con un gradiente personalizzato di GIMP.\n• Regola la transizione tra pendenze e piani tramite «Morbidezza smusso (%)».'}, 'dual_profile_cut': {'title': 'Sezione trasversale interattiva e ampiezza di transizione', 'short': 'Mostra dal vivo nella sezione dove agiscono colori di zona, scanalature, opacità e transizioni.', 'detail': '• La sezione mostra il profilo dal bordo esterno (sinistra) alla zona interna (destra).\n• A destra indica dal vivo se l’interno è aperto o piastra con l’opacità scelta (%).\n• Le bande gialle evidenziano l’ampiezza di transizione attiva («Morbidezza smusso»).\n• Nella scheda 5 clicca su Z1..Zn nel grafico per mettere a fuoco la riga corrispondente.'}, 'light_vector': {'title': 'Vettore luce 2D, sorgente (Fascio vs. Cono) e impatto', 'short': 'Controlla graficamente origine -> punto d’impatto, angolo (°), intensità (%) e larghezza/diametro.', 'detail': '• Trascina nel pad 2D dal punto giallo di origine alla punta della freccia:\n  - La direzione imposta l’angolo d’incidenza (0°–360°, predefinito 135°).\n  - La lunghezza regola l’intensità speculare (%).\n• Cono di luce (Cone): faretto con diametro regolabile (%).\n• Fascio di luce (Beam): banda luminosa lineare con larghezza regolabile (%).'}, 'inner_shimmer': {'title': 'Bagliore interno lungo il contorno', 'short': 'Proietta un morbido bagliore metallico dal bordo interno della cornice verso il centro.', 'detail': 'Il bagliore interno segue il contorno più interno della cornice e può seguire la luce principale, illuminare in alto a sinistra, in controluce (basso-destra) o su tutti i lati.'}, 'surface_finish': {'title': 'Finitura: Spazzolato, Grana, Piume, Pelo e Scaglie', 'short': 'Regola la finitura da Specchio e Satinato a Spazzolato, Grana, Piume, Pelo e Scaglie.', 'detail': '• Specchio / Satinato: riflesso lucido o satinatura morbida.\n• Spazzolato: linee direzionali fini con grana e angolo regolabili.\n• Grana: micro-grana uniforme senza linee di spazzolatura.\n• Piume, Pelo e Scaglie: trame organiche con dimensione, lunghezza, densità e direzione.\n• Direzione «Segue la luce» (-1) o angolo fisso (0° = destra).'}, 'lighting_glow': {'title': 'Effetti luce, Lucentezza e Bagliore (Bloom)', 'short': 'Controlla luce automatica, riflessi speculari, bagliore (Bloom), contrasto smusso e bagliore interno.', 'detail': '• Luce automatica (da Community) o pad 2D Cono/Fascio (Atelier).\n• Lucentezza e Bagliore (Bloom): aggiungono un alone luminoso morbido sui riflessi.\n• Contrasto smusso e bagliore interno: definiscono rilievo e bordo interno.'}, 'support': {'title': 'Supporto', 'short': 'Il supporto è fornito solo per Look, Atelier e Team.', 'detail': 'Il supporto è fornito solo per Look, Atelier e Team.\nContatto: https://www.ready-4-it.com/contact'}}
